import{_ as a}from"./chunks/daily-2026-08-20-report-attribution-figure-1.DYs6BrUv.js";import{_ as i,C as n,o as r,c as s,E as o,a2 as c}from"./chunks/framework.Cm6XCzck.js";const y=JSON.parse('{"title":"Three Agents Returned Three Reports. How Do You Keep Acceptance from Charging the Wrong Task?","description":"","frontmatter":{"title":"Three Agents Returned Three Reports. How Do You Keep Acceptance from Charging the Wrong Task?","date":"2026-08-20","column":"digital-employee","category":"daily","article_type":"project-research","edition":"research-center","research_question":"How can a multi-Agent acceptance system prove which task and execution attempt each report belongs to without guessing from prose?","summary":"Display may assist with parenting, but acceptance must verify task identity, execution attempt, supersession, and independent QA. The article defines the three-field gate’s limits and a safer artifact-version contract.","item_id":"MANUAL-20260820-REPORT-ATTRIBUTION","lifecycle":"Published","cover":"/assets/covers/daily-2026-08-20-report-attribution-cover.png","evidence_status":"Completed","citation_status":"Completed","editing_status":"Completed","publication_authorized":true,"sources":["research/manual-runs/2026-08-20-guided-article-pipeline-round1/02-source-register.md","research/manual-runs/2026-08-20-guided-article-pipeline-round1/02-fact-claim-matrices.md","research/manual-runs/2026-08-20-guided-article-pipeline-round1/02-article-briefs.md","research/manual-runs/2026-08-20-guided-article-pipeline-round1/02-experiment-run-log.md","research/manual-runs/2026-08-20-guided-article-pipeline-round1/02-independent-editorial-review-round4.md","research/manual-runs/2026-08-20-guided-article-pipeline-round1/03-independent-visual-package-review.md"]},"headers":[],"relativePath":"en/digital-employee/2026-08-20-report-attribution.md","filePath":"en/digital-employee/2026-08-20-report-attribution.md","lastUpdated":1787377515000}'),l={name:"en/digital-employee/2026-08-20-report-attribution.md"};function d(p,e,h,u,m,f){const t=n("ArticleCover");return r(),s("div",null,[o(t,{image:"/assets/covers/daily-2026-08-20-report-attribution-cover.png",kicker:"Digital Employee · Project Research",title:"Three Agents Returned Three Reports. How Do You Keep Acceptance from Charging the Wrong Task?",summary:"Display may assist with parenting, but acceptance must verify task identity, execution attempt, supersession, and independent QA.",version:"MANUAL-20260820-REPORT-ATTRIBUTION",status:"Community Readability PASS · 2026-08-22",languageHref:"/zh/digital-employee/2026-08-20-report-attribution",languageLabel:"中文"}),e[0]||(e[0]=c(`<h1 id="three-agents-returned-three-reports-how-do-you-keep-acceptance-from-charging-the-wrong-task" tabindex="-1">Three Agents Returned Three Reports. How Do You Keep Acceptance from Charging the Wrong Task? <a class="header-anchor" href="#three-agents-returned-three-reports-how-do-you-keep-acceptance-from-charging-the-wrong-task" aria-label="Permalink to &quot;Three Agents Returned Three Reports. How Do You Keep Acceptance from Charging the Wrong Task?&quot;">​</a></h1><p>A development agent, a QA agent, and an operations agent return reports at almost the same time. All three say “success,” so the system produces a reassuring summary: implementation complete, tests passed, deployment healthy.</p><p>But QA tested the pre-rework version. The operations report belongs to a different root task in the same thread. The developer report’s filename contradicts the task identifier in its metadata. No file is missing; three real artifacts have been assembled into a delivery that never existed.</p><p>The remedy is not another language model reading the prose. The runtime must bind each receipt to a unique task and execution attempt, keep display placement separate from acceptance ownership, and stop when ownership remains ambiguous. This article gives you an identity gate, a report-version state model, and a final-summary checklist that can be applied to your own Agent runtime.</p><p>Start with three plain questions:</p><table tabindex="0"><thead><tr><th>Attribution question</th><th>What it means</th><th>What can establish it</th></tr></thead><tbody><tr><td>Who did the work?</td><td>which project, task, and execution produced this report</td><td>task identity, parent, project root, and a runtime-recorded attempt</td></tr><tr><td>What proves the claim?</td><td>whether “success” is backed by machine evidence</td><td>the actual command, exit code, raw test output, and captured code version</td></tr><tr><td>Which contract accepts it?</td><td>which task owns the evidence and who may accept it</td><td>unique task binding, report supersession, independent QA, and final acceptance</td></tr></tbody></table><p>These questions prevent three different failures: charging A’s report to B, treating model-written prose as a test log, and allowing the executor to accept its own work. The current CodeFlowMu implementation provides hard checks on selected consequential paths. Runtime injection of every authoritative field remains a target contract.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>task dispatch</span></span>
<span class="line"><span>  → bind task and execution context</span></span>
<span class="line"><span>  → agent invokes tools</span></span>
<span class="line"><span>  → capture command, exit code, tests, and code version</span></span>
<span class="line"><span>  → assemble the report envelope</span></span>
<span class="line"><span>  → verify task, attempt, and report version</span></span>
<span class="line"><span>  → independent QA</span></span>
<span class="line"><span>  → authorized acceptance or rejection</span></span></code></pre></div><p>Not every arrow is uniformly implemented across every current tool and report path. The article distinguishes existing checks from the target design.</p><h2 id="a-report-can-exist-without-belonging-to-this-task" tabindex="-1">A report can exist without belonging to this task <a class="header-anchor" href="#a-report-can-exist-without-belonging-to-this-task" aria-label="Permalink to &quot;A report can exist without belonging to this task&quot;">​</a></h2><p>Multi-agent systems often use four convenient association rules:</p><ol><li>attach reports to the same chat thread;</li><li>attach them to the most recent task;</li><li>scan the body for a task identifier;</li><li>match the sender role—for example, attach a DEV report to the nearest development task.</li></ol><p>These rules can organize a screen, but none is sufficient for acceptance. A thread may contain multiple root tasks. A rework report may discuss the rejected predecessor. A body can mention both a parent and a child. An old report may be discovered only after a watcher restarts.</p><p>Choosing the “most likely” task produces a plausible tree, not deterministic evidence ownership.</p><h2 id="a-report-needs-several-identities" tabindex="-1">A report needs several identities <a class="header-anchor" href="#a-report-needs-several-identities" aria-label="Permalink to &quot;A report needs several identities&quot;">​</a></h2><p>CodeFlowMu currently uses four kinds of attribution information:</p><table tabindex="0"><thead><tr><th>Identity</th><th>Purpose</th><th>Typical failure</th></tr></thead><tbody><tr><td>report file identity</td><td>identifies this receipt occurrence</td><td>filename sequence points to another task</td></tr><tr><td><code>task_id</code></td><td>declares the direct work owner</td><td>still points to the pre-rework task</td></tr><tr><td><code>parent_task_id</code></td><td>places the report in the task tree</td><td>attaches to the root instead of the worker child</td></tr><tr><td><code>references</code></td><td>preserves related tasks and historical links</td><td>treats “mentioned” as “directly owned by”</td></tr></tbody></table><p>Direct ownership and historical relevance are different relationships.</p><p>If a developer reworks <code>TASK-042-REWORK-01</code>, the report may retain <code>TASK-042</code> in <code>references</code> to explain why rework occurred. Its direct <code>task_id</code> should identify the current rework task. A resolver that scans references without respecting the direct owner can let the predecessor steal the new report.</p><h2 id="consequential-receipts-need-a-hard-gate" tabindex="-1">Consequential receipts need a hard gate <a class="header-anchor" href="#consequential-receipts-need-a-hard-gate" aria-label="Permalink to &quot;Consequential receipts need a hard gate&quot;">​</a></h2><p>For one consequential DEV receipt path, CodeFlowMu implements a strict three-way check in <a href="https://github.com/joinwell52-AI/CodeFlowMu-open/blob/ed5634c718b9e238c44bb70851020c9793546fe6/packages/codeflowmu-runtime/src/pm/reportAttribution.ts" target="_blank" rel="noreferrer"><code>reportAttribution.ts</code></a>:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>TASK inferred from the REPORT filename</span></span>
<span class="line"><span>        ==</span></span>
<span class="line"><span>frontmatter.task_id</span></span>
<span class="line"><span>        ==</span></span>
<span class="line"><span>references[0]</span></span></code></pre></div><p>Example:</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">filename</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">REPORT-20260820-042-DEV-to-PM.md</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">task_id</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">TASK-20260820-042</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">references</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">TASK-20260820-042</span></span></code></pre></div><p>If the filename identifies 043 while the explicit task and first reference identify 042, attribution fails. The gate does not take a two-out-of-three vote. Missing explicit identity also fails.</p><p>This boundary needs precision. It is an application-level CodeFlowMu rule for a key DEV acceptance path, not a universal FCoP naming rule for every report and every role. FCoP defines report envelopes and references; a host runtime may add stricter contracts for consequential workflows.</p><p>The check rejects disagreement. It cannot detect three fields that all repeat the same wrong task identifier—for example, when a model copies an old template and changes nothing. A stronger target design lets the Agent submit only the report body and evidence; the runtime injects the filename, direct owner, parent, execution attempt, and logical event sequence from the active execution context. That is a design recommendation, not a claim that every current CodeFlowMu report path already provides this envelope-injection contract.</p><p><img src="`+a+`" alt="Task identity and execution attempt bind development facts and QA verification; supersession selects the effective artifact and isolates the wrong owner"></p><p><em>Figure 1. Attribution from task identity and execution attempt through supersession and QA. Source: author synthesis from the pinned CodeFlowMu implementation and W3C/OpenTelemetry identity-propagation boundaries. Runtime injection of all authoritative metadata remains a target contract.</em></p><h2 id="a-practical-attribution-veto-list" tabindex="-1">A practical attribution veto list <a class="header-anchor" href="#a-practical-attribution-veto-list" aria-label="Permalink to &quot;A practical attribution veto list&quot;">​</a></h2><p>A useful gate needs explicit rejection conditions. Rejection here means stale, conflicting, or insufficient evidence—not an accusation of malicious fraud:</p><ul><li>the report’s code version differs from the workspace that was actually tested: quarantine it as stale or conflicting evidence;</li><li>the report says “tests passed” but lacks the command, exit code, or raw output: do not admit it to a success summary;</li><li>filename, task field, and first reference agree with each other but disagree with the runtime’s dispatch record: attribution fails;</li><li>one task has several reports without an attempt number or explicit supersession relation: do not guess which file wins;</li><li>file modification time is the only ordering signal: it cannot establish causality;</li><li>an expired execution right may veto a report only on paths that actually implement such a bounded right; do not invent lease semantics elsewhere.</li></ul><p>The safe result is often <code>undetermined</code>. That is preferable to assembling three genuine artifacts into a delivery that never happened.</p><h2 id="propagate-identity—but-do-not-confuse-tracing-with-acceptance" tabindex="-1">Propagate identity—but do not confuse tracing with acceptance <a class="header-anchor" href="#propagate-identity—but-do-not-confuse-tracing-with-acceptance" aria-label="Permalink to &quot;Propagate identity—but do not confuse tracing with acceptance&quot;">​</a></h2><p>Distributed systems already use explicit correlation. W3C <a href="https://www.w3.org/TR/trace-context/" target="_blank" rel="noreferrer">Trace Context</a> carries a <code>trace-id</code> across services. Its <code>parent-id</code> identifies the caller’s operation for the incoming request; a downstream participant replaces it with the identifier of its current operation when propagating context. The OpenTelemetry <a href="https://opentelemetry.io/docs/specs/otel/trace/api/" target="_blank" rel="noreferrer">Tracing API</a> gives each span at most one parent; parent and child share a TraceId and form a causal tree.</p><p>The useful lesson for agent work is that task identity and parentage should travel with execution. They should not be reconstructed from prose after a report arrives.</p><p>The analogy then stops. A trace proves correlation, not correctness. An ended span is not a business acceptance. Agent systems should preserve the same separations:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>correct correlation</span></span>
<span class="line"><span>      ≠</span></span>
<span class="line"><span>truthful report content</span></span>
<span class="line"><span>      ≠</span></span>
<span class="line"><span>independent verification</span></span>
<span class="line"><span>      ≠</span></span>
<span class="line"><span>business acceptance</span></span></code></pre></div><h2 id="display-may-make-a-best-effort-acceptance-may-not-guess" tabindex="-1">Display may make a best effort; acceptance may not guess <a class="header-anchor" href="#display-may-make-a-best-effort-acceptance-may-not-guess" aria-label="Permalink to &quot;Display may make a best effort; acceptance may not guess&quot;">​</a></h2><p>CodeFlowMu’s <a href="https://github.com/joinwell52-AI/CodeFlowMu-open/blob/ed5634c718b9e238c44bb70851020c9793546fe6/packages/codeflowmu-runtime/src/ledger/reportParenting.ts" target="_blank" rel="noreferrer"><code>reportParenting.ts</code></a> must handle incomplete historical data. It prefers explicit <code>source_task_id</code> or <code>task_id</code>. When those are absent, it can inspect references, filename sequence, body overlap, and recent open tasks to place a report in a useful ledger view.</p><p>That best-effort reconstruction is valuable: legacy reports do not all become orphans.</p><p>It is unsafe as an acceptance rule. Two tasks can mention the same module. “Most recent” is a timing coincidence. One role can own several concurrent tasks.</p><p>The system therefore needs two outputs:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>display_parent = best_effort_match(...)</span></span>
<span class="line"><span>acceptance_owner = deterministic_contract_or_undetermined(...)</span></span></code></pre></div><p>The display parent may be labeled as inferred and corrected by a human. The acceptance owner must be unique, or <code>undetermined</code>. Uncertainty is not a failure to be hidden; it is the result that prevents false accounting.</p><h2 id="a-thread-cannot-be-the-parent-when-it-has-multiple-roots" tabindex="-1">A thread cannot be the parent when it has multiple roots <a class="header-anchor" href="#a-thread-cannot-be-the-parent-when-it-has-multiple-roots" aria-label="Permalink to &quot;A thread cannot be the parent when it has multiple roots&quot;">​</a></h2><p>One conversation can handle defect A and later introduce independent feature B. If reports carry only the shared <code>thread_key</code>, an old final report can be reused by the new root.</p><p>The current parenting code partitions a thread with multiple ADMIN roots by lineage and task prefix. A report enters a root bucket only when references or parentage uniquely identify it. Otherwise it remains isolated rather than attaching to the first root in the thread.</p><p>This improves ledger reconstruction; it cannot recover identity that was never recorded. Some legacy artifacts require an authorized human decision. A tidy tree is not worth invented certainty.</p><h2 id="two-reports-for-one-task-need-an-explicit-winner" tabindex="-1">Two reports for one task need an explicit winner <a class="header-anchor" href="#two-reports-for-one-task-need-an-explicit-winner" aria-label="Permalink to &quot;Two reports for one task need an explicit winner&quot;">​</a></h2><p>The same task may produce a failed report, a corrected report, and a retry after restart. Overwriting the old file destroys evidence. Treating every file as equally current lets an obsolete failure or success leak into the final summary.</p><p>CodeFlowMu&#39;s current ledger can read <code>submission_attempt</code>, <code>revision_of</code>, <code>supersedes</code>, and <code>superseded_by</code>, while the summary gate excludes reports marked invalid or superseded. These are useful building blocks. They do not prove that every report writer automatically increments attempts or that every competing report is uniquely arbitrated.</p><p>A complete target contract needs three separate identities:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>task identity</span></span>
<span class="line"><span>    └── execution attempt 1</span></span>
<span class="line"><span>          ├── report v1 ── rejected</span></span>
<span class="line"><span>          └── report v2 ── effective, supersedes v1</span></span>
<span class="line"><span>    └── execution attempt 2 ── starts only after an explicit retry decision</span></span></code></pre></div><p>Use the logical event sequence, attempt identity, and explicit supersession relationship to decide which receipt is effective. File modification time can help an operator investigate, but it should not be the sole judge.</p><h2 id="correct-attribution-still-does-not-authorize-a-final-summary" tabindex="-1">Correct attribution still does not authorize a final summary <a class="header-anchor" href="#correct-attribution-still-does-not-authorize-a-final-summary" aria-label="Permalink to &quot;Correct attribution still does not authorize a final summary&quot;">​</a></h2><p>Even after a developer report is attached to the right task, a project manager cannot automatically declare success. <a href="https://github.com/joinwell52-AI/CodeFlowMu-open/blob/ed5634c718b9e238c44bb70851020c9793546fe6/packages/codeflowmu-runtime/src/pm/PmSummaryGate.ts" target="_blank" rel="noreferrer"><code>PmSummaryGate</code></a> also checks whether downstream children are settled; whether an effective worker report exists; whether it postdates the task; whether product work has the required QA report; whether QA returned PASS; whether required browser evidence exists; and whether an effective final summary already exists.</p><p>An empty diagnostics list is not attribution success. A DEV report is not QA. A PM summary is not final business acceptance.</p><p>This is the engineering value of TMPA’s fact/acceptance separation: executors submit facts, verifiers examine facts, and authorized roles decide acceptance. A single <code>status: done</code> field must not merge all three.</p><p>Time also needs a boundary. Current compatibility paths can use explicit artifact timestamps and, for older files, filesystem modification time. Git checkout, archive extraction, cross-device copy, or clock skew can all change physical timestamps. Consequential acceptance should therefore prefer logical sequence, execution attempt, and explicit supersession; wall-clock time remains supporting evidence.</p><h2 id="what-44-passing-tests-cover" tabindex="-1">What 44 passing tests cover <a class="header-anchor" href="#what-44-passing-tests-cover" aria-label="Permalink to &quot;What 44 passing tests cover&quot;">​</a></h2><p>For this article we pinned CodeFlowMu Open commit <code>ed5634c718b9e238c44bb70851020c9793546fe6</code> in an isolated worktree and reran the parenting, attribution, and summary-gate suites. The result was <strong>44 of 44 tests passing</strong>.</p><p>The cases include a filename identifying task 003 while metadata and references identify 002; missing task identity; a valid three-way match; a rework report staying with its explicit current owner even when it references a predecessor; two roots in one thread; a late report that predates its child task; missing or failing QA; missing browser evidence; and a zero-diagnostic state that still fails because attribution is invalid.</p><p>The tests also confirm that best-effort parenting uses body and recent-task fallbacks. We therefore do not claim that every historical CodeFlowMu report is determined exclusively by the three-way gate. The accurate boundary is: compatibility logic helps organize incomplete data; consequential acceptance paths use stricter contracts.</p><p>The suite does not prove that three consistently wrong identifiers will be detected, that every writer injects authoritative metadata, or that clock skew and competing attempts are fully arbitrated. Those remain explicit next-test targets.</p><h2 id="six-failure-cases-to-copy" tabindex="-1">Six failure cases to copy <a class="header-anchor" href="#six-failure-cases-to-copy" aria-label="Permalink to &quot;Six failure cases to copy&quot;">​</a></h2><h3 id="identifier-mismatch" tabindex="-1">Identifier mismatch <a class="header-anchor" href="#identifier-mismatch" aria-label="Permalink to &quot;Identifier mismatch&quot;">​</a></h3><p>Make the filename, explicit task, and first reference disagree. Expected: attribution fails; the original artifact and conflict evidence remain intact.</p><h3 id="consistently-wrong-identifiers" tabindex="-1">Consistently wrong identifiers <a class="header-anchor" href="#consistently-wrong-identifiers" aria-label="Permalink to &quot;Consistently wrong identifiers&quot;">​</a></h3><p>Copy an old report template so that the filename, <code>task_id</code>, and first reference all agree on the wrong task. Expected target behavior: runtime-owned execution context overrides or rejects model-authored identity. A three-way equality check alone is insufficient.</p><h3 id="late-old-report" tabindex="-1">Late old report <a class="header-anchor" href="#late-old-report" aria-label="Permalink to &quot;Late old report&quot;">​</a></h3><p>Create a report before the target child exists, then discover it after a watcher restart. Expected: it may appear as historical evidence, but cannot satisfy the current child’s report requirement.</p><h3 id="repeated-submission-for-one-task" tabindex="-1">Repeated submission for one task <a class="header-anchor" href="#repeated-submission-for-one-task" aria-label="Permalink to &quot;Repeated submission for one task&quot;">​</a></h3><p>Submit v1, reject it, then submit v2 for the same task. Expected: both artifacts remain auditable, v2 explicitly supersedes v1, and only one version is effective for the current attempt.</p><h3 id="multiple-roots-in-one-thread" tabindex="-1">Multiple roots in one thread <a class="header-anchor" href="#multiple-roots-in-one-thread" aria-label="Permalink to &quot;Multiple roots in one thread&quot;">​</a></h3><p>Place two independent roots under one <code>thread_key</code> and supply no lineage. Expected: <code>undetermined</code>, not first-root or newest-root attachment.</p><h3 id="missing-or-failed-qa" tabindex="-1">Missing or failed QA <a class="header-anchor" href="#missing-or-failed-qa" aria-label="Permalink to &quot;Missing or failed QA&quot;">​</a></h3><p>Provide a correctly attributed DEV report and valid code, but omit required QA or set the verdict to FAIL. Expected: no successful final summary and no downstream publication release.</p><h2 id="a-report-and-summary-checklist" tabindex="-1">A report and summary checklist <a class="header-anchor" href="#a-report-and-summary-checklist" aria-label="Permalink to &quot;A report and summary checklist&quot;">​</a></h2><p>At task execution:</p><ol><li>Put task, parent, and execution-attempt identity into the runtime context when work is claimed.</li><li>Let the Agent submit body and evidence; let the runtime inject the filename and authoritative metadata.</li><li>Store the direct owner separately from historical references.</li><li>Record sender role, attempt identity, logical event sequence, and physical timestamp.</li><li>Give rework a new attempt identity and an explicit supersession link while retaining predecessor references.</li></ol><p>At report intake:</p><ol start="6"><li>Parse explicit identity before running heuristic matching.</li><li>Return undetermined when candidates tie.</li><li>Preserve the original file, parse result, and conflict reason.</li><li>Clearly label inferred display placement as unusable for acceptance.</li></ol><p>Before final summary:</p><ol start="10"><li>Use logical sequence, attempt identity, and supersession to select the effective report; use physical time only as supporting evidence.</li><li>Verify role, owner, and required evidence.</li><li>Block success on missing, failed, or insufficient QA.</li><li>Store execution facts, verification decisions, and business acceptance separately.</li></ol><h2 id="limits-and-open-questions" tabindex="-1">Limits and open questions <a class="header-anchor" href="#limits-and-open-questions" aria-label="Permalink to &quot;Limits and open questions&quot;">​</a></h2><p>A consistent three-way identifier catches obvious cross-accounting. It does not prove truthful report content. A model can consistently repeat the wrong identity, so runtimes should inject task identity rather than ask models to generate it. The current sources do not prove that this injection contract is universal across CodeFlowMu report writers.</p><p>The body-matching heuristic has no measured false-association rate, and this article does not recommend it for acceptance. Cross-repository and cross-organization tasks also need namespaces or globally unique identities; a date plus a three-digit sequence can collide.</p><p>The 44 tests are first-party evidence from a pinned commit, not an external audit. A stronger next experiment would generate random task trees, copy consistently wrong metadata, create competing attempts, reorder reports, skew physical timestamps, duplicate watcher events, rebuild after restart, and measure undetermined, false-attachment, and missed-attachment rates.</p><h2 id="conclusion" tabindex="-1">Conclusion <a class="header-anchor" href="#conclusion" aria-label="Permalink to &quot;Conclusion&quot;">​</a></h2><p>The most dangerous multi-agent reporting error is not always a missing artifact. It is a plausible artifact charged to the wrong task and then propagated into acceptance.</p><blockquote><p>A display may help a human find a report. An acceptance system has no authority to guess when ownership is unclear.</p></blockquote><p>Propagate task identity and parentage with execution. Apply deterministic attribution to consequential receipts. Keep QA and final acceptance independent. Three reports can then remain three reviewable evidence chains instead of becoming one convincing false delivery.</p><h2 id="primary-sources" tabindex="-1">Primary sources <a class="header-anchor" href="#primary-sources" aria-label="Permalink to &quot;Primary sources&quot;">​</a></h2><ol><li><a href="https://www.w3.org/TR/trace-context/" target="_blank" rel="noreferrer">W3C Trace Context</a></li><li><a href="https://opentelemetry.io/docs/specs/otel/trace/api/" target="_blank" rel="noreferrer">OpenTelemetry Tracing API</a></li><li><a href="https://github.com/joinwell52-AI/FCoP/blob/a859e6747fe6e5e2d686e0114c77774726d7f748/spec/fcop-v3-spec.zh.md" target="_blank" rel="noreferrer">FCoP v3 Chinese specification, pinned commit</a></li><li><a href="https://github.com/joinwell52-AI/CodeFlowMu-open/blob/ed5634c718b9e238c44bb70851020c9793546fe6/packages/codeflowmu-runtime/src/pm/reportAttribution.ts" target="_blank" rel="noreferrer">CodeFlowMu reportAttribution, pinned commit</a></li><li><a href="https://github.com/joinwell52-AI/CodeFlowMu-open/blob/ed5634c718b9e238c44bb70851020c9793546fe6/packages/codeflowmu-runtime/src/ledger/reportParenting.ts" target="_blank" rel="noreferrer">CodeFlowMu reportParenting, pinned commit</a></li><li><a href="https://github.com/joinwell52-AI/CodeFlowMu-open/blob/ed5634c718b9e238c44bb70851020c9793546fe6/packages/codeflowmu-runtime/src/pm/PmSummaryGate.ts" target="_blank" rel="noreferrer">CodeFlowMu PmSummaryGate, pinned commit</a></li><li><a href="https://github.com/joinwell52-AI/CodeFlowMu-open/blob/ed5634c718b9e238c44bb70851020c9793546fe6/packages/codeflowmu-runtime/src/ledger/LedgerBuilder.ts" target="_blank" rel="noreferrer">CodeFlowMu LedgerBuilder, pinned commit</a></li><li><a href="https://github.com/joinwell52-AI/joinwell52/blob/ae27de71b1a8809c2bd69acedc1482570d55a322/docs/public/releases/tmpa/v1.0/artifacts/tmpa-core-specification-s1.0-zh.md" target="_blank" rel="noreferrer">TMPA Core Specification S1.0, pinned commit</a></li></ol><p>Accessed 2026-08-20.</p>`,96))])}const k=i(l,[["render",d]]);export{y as __pageData,k as default};
